package id.homebase.api.image

import kotlin.io.encoding.Base64

// 64x32 HEIC from macOS ImageIO, rotated by irot (EXIF Orientation 6), with GPS 37.7749 N 122.4194 W,
// BodySerialNumber SECRETSERIAL, Make SecretCamera and an XMP item. Items: Exif 572..824,
// XMP 824..3227, hvc1 3227..3319; everything before 572 is ftyp + meta.
internal object HeicFixtures {
    val geotaggedRotated: ByteArray get() = Base64.decode(GEOTAGGED_ROTATED)

    private const val GEOTAGGED_ROTATED =
        ""
}
